@startuml

class Person {
  + FirstName : string
  + LastName : string
  + BirthDate : date
}

class Trainer {
  + Diploma : string
}

class Center {
  + Name : string
  + Address : string
}

abstract class Room {
  + MaxCapacity : int
}

class IndividualSession {
  + Date : date
  + StartHour : time
}

class GroupSession {
  + Date : date
  + StartHour : time
  + Type : string
}

class Participant {}

class TrainerSupervision {}

Person "1" -- "*" Participant
Trainer "1" -- "*" TrainerSupervision
Center "1" *-- "*" Room
Room "1" *-- "*" IndividualSession
Room "1" *-- "*" GroupSession
GroupSession "0..1" -- "1" TrainerSupervision

@enduml

